```r
###############################################################
## Align all kmers
###############################################################

aligned <- data.frame(
    sequence=reference,
    weight=max(kmers$weight),
    offset=0
)

rejected <- data.frame()

for(i in seq_len(nrow(kmers)))
{

    if(kmers$sequence[i]==reference)
        next

    offset <- rbns_alignment(
        kmers$sequence[i],
        reference
    )

    if(is.na(offset))
    {

        rejected <- rbind(
            rejected,
            kmers[i,]
        )

    }
    else
    {

        aligned <- rbind(
            aligned,
            data.frame(
                sequence=kmers$sequence[i],
                weight=kmers$weight[i],
                offset=offset
            )
        )

    }

}



write.csv(
    aligned,
    paste0(output_prefix,\_aligned_5mers.csv\")
